-- Demo students for local development / manual testing of Phases 4-10.
-- Tokens here are simple demo values; production tokens are generated by
-- the app's nanoid-based QR service (Phase 5), not hand-written SQL.

insert into public.students (
  student_code, student_token, khmer_first_name, khmer_last_name,
  english_first_name, english_last_name, gender, date_of_birth, place_of_birth,
  phone, email, address, province, district, commune, village,
  department_id, study_program_id, class_id, academic_year_id,
  study_year, semester, gpa, credits_earned, status, issue_date, expiry_date
)
select
  v.student_code, v.student_token, v.khmer_first_name, v.khmer_last_name,
  v.english_first_name, v.english_last_name, v.gender, v.date_of_birth::date, v.place_of_birth,
  v.phone, v.email, v.address, v.province, v.district, v.commune, v.village,
  d.id, sp.id, c.id, ay.id,
  v.study_year, v.semester, v.gpa, v.credits_earned, v.status,
  v.issue_date::date, v.expiry_date::date
from (values
  ('STU-2026-0001', 'A83KD93LQ2P', 'សុភា', 'គឹម', 'Sophea', 'Kim', 'female', '2009-03-14', 'Phnom Penh',
   '012345678', 'sophea.kim@example.com', '#12, St. 210', 'Phnom Penh', 'Chamkar Mon', 'Tonle Bassac', 'Village 1',
   'SCI', 'SCI-GEN', 'Grade 10A', 10, 1, 3.65, 12, 'active', '2025-11-01', '2028-08-31'),
  ('STU-2026-0002', 'B71PZ44XN9Q', 'សុវណ្ណ', 'ចាន់', 'Sovann', 'Chan', 'male', '2008-07-22', 'Kandal',
   '098765432', 'sovann.chan@example.com', 'Phum Prek Ta Nu', 'Kandal', 'Ta Khmau', 'Ta Khmau', 'Village 3',
   'SOC', 'SOC-GEN', 'Grade 11B', 11, 2, 3.10, 20, 'active', '2025-11-01', '2028-08-31'),
  ('STU-2026-0003', 'C25MN18RT4K', 'ចន្ទា', 'សេង', 'Chantha', 'Seng', 'female', '2007-01-09', 'Siem Reap',
   '011223344', 'chantha.seng@example.com', 'Wat Bo Road', 'Siem Reap', 'Siem Reap', 'Wat Bo', 'Village 5',
   'IT', 'IT-GEN', 'Grade 12C', 12, 1, 3.92, 30, 'active', '2024-11-01', '2027-08-31'),
  ('STU-2026-0004', 'D66QW82VB1S', 'បញ្ញា', 'ឡុង', 'Panha', 'Long', 'male', '2009-11-30', 'Battambang',
   '077889900', 'panha.long@example.com', 'Street 3', 'Battambang', 'Battambang', 'Svay Por', 'Village 2',
   'SCI', 'SCI-GEN', 'Grade 10A', 10, 1, 2.85, 10, 'inactive', '2025-11-01', '2028-08-31'),
  ('STU-2026-0005', 'E39JK71HD6M', 'រតនា', 'ភន់', 'Reaksa', 'Phon', 'male', '2006-05-18', 'Kampot',
   '099001122', 'reaksa.phon@example.com', 'Kampot Riverside', 'Kampot', 'Kampot', 'Kampong Kandal', 'Village 4',
   'IT', 'IT-GEN', 'Grade 12C', 12, 2, 3.40, 28, 'graduated', '2023-11-01', '2026-08-31')
) as v(
  student_code, student_token, khmer_first_name, khmer_last_name, english_first_name, english_last_name,
  gender, date_of_birth, place_of_birth, phone, email, address, province, district, commune, village,
  dept_code, program_code, class_name, study_year, semester, gpa, credits_earned, status, issue_date, expiry_date
)
join public.departments d on d.code = v.dept_code
join public.study_programs sp on sp.code = v.program_code
join public.academic_years ay on ay.is_current
join public.classes c on c.name = v.class_name and c.academic_year_id = ay.id
on conflict (student_code) do nothing;
